INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > 3D-Drucker
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können 3D-Drucker unabhängig von der Materialkompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Drucker müssen mit Filament oder Harz kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Material bestimmt Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines 3D-Druckers immer die Anforderungen an die Druckgenauigkeit berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Genauigkeit entscheidet über Qualität"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines 3D-Druckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Beeinflusst Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können 3D-Drucker ohne Rücksicht auf die Softwarekompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Software steuert Druckprozess"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind teurere 3D-Drucker immer besser als günstigere Modelle?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Anforderungen ab"}, {"text": "Ja", "correct": false, "because": "Preis ≠ Leistung"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines 3D-Druckers am wichtigsten?', 3, '[{"text": "Druckanforderungen", "correct": true, "because": "Bestimmen Material und Präzision"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird bei den meisten Hobby-3D-Druckern verwendet?', 2, '[{"text": "FDM", "correct": true, "because": "Fused Deposition Modeling ist kostengünstig"}, {"text": "SLA", "correct": false, "because": "Stereolithografie teurer"}, {"text": "SLS", "correct": false, "because": "Selektives Lasersintern komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird zur Messung der Druckgenauigkeit eines 3D-Druckers verwendet?', 2, '[{"text": "Mikrometer (µm)", "correct": true, "because": "Gibt Schichtdicke an"}, {"text": "Watt (W)", "correct": false, "because": "Leistungsaufnahme"}, {"text": "GB", "correct": false, "because": "Speichergröße"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Material ist für FDM-3D-Drucker am häufigsten?', 3, '[{"text": "PLA", "correct": true, "because": "Einfach zu drucken, biologisch abbaubar"}, {"text": "ABS", "correct": false, "because": "Robuster, aber schwieriger"}, {"text": "Resin", "correct": false, "because": "Für SLA, nicht FDM"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von 3D-Druckern im Prototyping?', 2, '[{"text": "Schnelle Produktion", "correct": true, "because": "Reduziert Entwicklungszeit"}, {"text": "Geringe Kosten", "correct": false, "because": "Material kann teuer sein"}, {"text": "Hohe Farbvielfalt", "correct": false, "because": "Sekundär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines 3D-Druckers?', 4, '[{"text": "Druckvolumen", "correct": true, "because": "Bestimmt Objektgröße"}, {"text": "Materialkompatibilität", "correct": true, "because": "Einsatzmöglichkeiten"}, {"text": "Druckgenauigkeit", "correct": true, "because": "Qualität des Ergebnisses"}, {"text": "Gewicht des Druckers", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die FDM-Technologie?', 3, '[{"text": "Kosteneffizienz", "correct": true, "because": "Günstige Materialien"}, {"text": "Einfache Bedienung", "correct": true, "because": "Weniger komplex"}, {"text": "Breite Materialauswahl", "correct": true, "because": "PLA, ABS etc."}, {"text": "Maximale Präzision", "correct": false, "because": "SLA präziser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei 3D-Druckern auftreten?', 3, '[{"text": "Materialverstopfung", "correct": true, "because": "Häufig bei FDM"}, {"text": "Unzureichende Präzision", "correct": true, "because": "Falsche Einstellung"}, {"text": "Lange Druckzeiten", "correct": true, "because": "Bei großen Objekten"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Materialien können in 3D-Druckern verwendet werden?', 4, '[{"text": "PLA", "correct": true, "because": "Für FDM geeignet"}, {"text": "ABS", "correct": true, "because": "Robuster Kunststoff"}, {"text": "Resin", "correct": true, "because": "Für SLA-Drucker"}, {"text": "Papier", "correct": false, "because": "Nicht für 3D-Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von 3D-Druckern?', 3, '[{"text": "Prototyping", "correct": true, "because": "Schnelle Modelle"}, {"text": "Medizin", "correct": true, "because": "Prothesen, Modelle"}, {"text": "Produktion", "correct": true, "because": "Kleine Serien"}, {"text": "Textverarbeitung", "correct": false, "because": "Nicht relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) FDM-Drucker sind kostengünstiger als SLA-Drucker. b) 3D-Drucker benötigen keine spezielle Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "FDM ja, Software nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Druckgenauigkeit wird in Mikrometern gemessen. b) PLA ist schwieriger zu drucken als ABS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "µm ja, PLA einfacher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) 3D-Drucker können Metall drucken. b) Druckgeschwindigkeit ist bei Prototyping irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Metall ja (SLS), Geschwindigkeit relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) SLA-Drucker bieten höhere Präzision als FDM. b) Alle 3D-Drucker unterstützen alle Materialien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SLA präziser, Materialien spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) 3D-Drucker sind für kleine Serienproduktionen geeignet. b) Druckvolumen ist bei allen Modellen gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Serien ja, Volumen variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

